// A small subset of East Asian Ambiguous ranges, only consulted when ambiguousAsWide is requested.
const AMBIGUOUS_RANGES = [
	[0x00a1, 0x00a1], [0x00a4, 0x00a4], [0x00a7, 0x00a8], [0x00aa, 0x00aa], [0x00ad, 0x00ae], [0x00b0, 0x00b4],
	[0x00b6, 0x00ba], [0x00bc, 0x00bf], [0x00c6, 0x00c6], [0x00d0, 0x00d0], [0x00d7, 0x00d8], [0x00de, 0x00e1],
	[0x0391, 0x03a9], [0x03b1, 0x03c9], [0x0401, 0x0401], [0x0410, 0x044f], [0x0451, 0x0451], [0x2010, 0x2010],
	[0x2013, 0x2016], [0x2018, 0x2019], [0x201c, 0x201d], [0x2020, 0x2022], [0x2024, 0x2027], [0x2030, 0x2030],
	[0x2032, 0x2033], [0x2035, 0x2035], [0x203b, 0x203b], [0x203e, 0x203e], [0x2160, 0x216b], [0x2170, 0x2179],
	[0x2190, 0x2199], [0x2460, 0x24e9], [0x24eb, 0x254b], [0x2550, 0x2573], [0x2580, 0x258f], [0x2592, 0x2595],
	[0x25a0, 0x25a1], [0x25a3, 0x25a9], [0x25b2, 0x25b3], [0x25b6, 0x25b7], [0x25bc, 0x25bd], [0x25c0, 0x25c1],
	[0x25c6, 0x25c8], [0x25cb, 0x25cb], [0x25ce, 0x25d1], [0x25e2, 0x25e5], [0x25ef, 0x25ef], [0x2605, 0x2606],
	[0x2609, 0x2609], [0x260e, 0x260f], [0x261c, 0x261c], [0x261e, 0x261e], [0x2640, 0x2640], [0x2642, 0x2642],
	[0xe000, 0xf8ff], [0xfffd, 0xfffd],
];

function inRanges(ranges, codePoint) {
	let low = 0;
	let high = ranges.length - 1;
	while (low <= high) {
		const mid = (low + high) >> 1;
		const [start, end] = ranges[mid];
		if (codePoint < start) high = mid - 1;
		else if (codePoint > end) low = mid + 1;
		else return true;
	}
	return false;
}

function validate(codePoint) {
	if (!Number.isSafeInteger(codePoint)) {
		throw new TypeError(`Expected a code point, got \`${typeof codePoint}\`.`);
	}
}

export function eastAsianWidthType(codePoint) {
	validate(codePoint);
	if ((codePoint >= 0x3000 && codePoint <= 0x3000) || (codePoint >= 0xff01 && codePoint <= 0xff60) || (codePoint >= 0xffe0 && codePoint <= 0xffe6)) {
		return "fullwidth";
	}
	if (inRanges(WIDE_RANGES, codePoint)) return "wide";
	if (inRanges(AMBIGUOUS_RANGES, codePoint)) return "ambiguous";
	return "neutral";
}

export function eastAsianWidth(codePoint, { ambiguousAsWide = false } = {}) {
	validate(codePoint);
	if (inRanges(WIDE_RANGES, codePoint)) return 2;
	if (ambiguousAsWide && inRanges(AMBIGUOUS_RANGES, codePoint)) return 2;
	return 1;
}

export function _isWide(codePoint) {
	return inRanges(WIDE_RANGES, codePoint);
}
